void solve()
{
	int n, m;
	cin &gt;&gt; n &gt;&gt; m;
	vector&lt;int&gt; v(n + 2);
	for (int i = 1; i &lt;= n; i++) cin &gt;&gt; v[i]; 
	for (int i = n; i &gt;= 1; i--) v[i] -= v[i - 1];

	struct datas
	{
		int d, s, t;
	};
	vector&lt;datas&gt; k(m + 1);
	for (int i = 1; i &lt;= m; i++) cin &gt;&gt; k[i].d &gt;&gt; k[i].s &gt;&gt; k[i].t;

	int l = 1, r = m, mid, ans;
	while (l &lt;= r)
	{
		mid = l + (r - l) / 2;
		auto check = [&amp;]() -&gt; bool
		{
			auto b = v;
			for (int i = 1; i &lt;= mid; i++)
			{
				b[v[i].s] -= v[i].d;
				b[v[i].t + 1] += v[i].d;
			}
			int ans = 0;
			for (int i = 1; i &lt;= m; i++)
			{
				ans += b[i];
				if (b[i] &lt; 0) return 1;
			}
			return 0;
		};
		if (check()) r = (ans = mid) - 1;
		else l = mid + 1; 
	}
	cout &lt;&lt; ans;
}



