class Solution
{
public:
    int xor_(int x)
    {
        if (x % 4 == 0)
        {
            return x;
        }
        if (x % 4 == 1)
        {
            return 1;
        }
        if (x % 4 == 2)
        {
            return x + 1;
        }
        return 0;
    }

    int missingNumber(vector&lt;int&gt; &amp;nums)
    {
        int n = nums.size();

        // calculate xor from 0 to n

        int xor_1_to_n = xor_(n);

        // calculate xor from array
        int temp = 0;
        for (auto &amp;&amp;i : nums)
        {
            temp ^= i;
        }

        return xor_1_to_n ^ temp;
    }
};


