class Solution
{
public:
    vector&lt;int&gt; singleNumber(vector&lt;int&gt; &amp;nums)
    {
        unsigned xor_nums = 0;
        for (auto &amp;&amp;i : nums)
        {
            xor_nums ^= i;
        }

        int lowbit = xor_nums &amp; (-xor_nums);

        int res1 = 0;
        for (auto &amp;&amp;i : nums)
        {
            if (lowbit &amp; i)
            {
                res1 ^= i;
            }
        }
        return {res1, res1 ^ (int)xor_nums};
    }
};




