int findleft(vector&lt;int&gt; &amp;nums, int target)
{
    int l = 0, r = nums.size() - 1, mid;
    int ans = -1;

    while (l &lt;= r)
    {
        mid = l + ((r - l) &gt;&gt; 1);
        if (nums[mid] &gt;= target) // 满足条件 更新ans 并继续缩小范围
        {
            ans = mid;
            // 如何缩小范围? 这是一个单调的 现在发现数字大了 那么应该缩小右边界
            r = mid - 1;
        }
        else /* 当前数字太小了 那么应该找更大的 缩小左边界 */ l = mid + 1;
    }
    return ans; // 如果没有找到结果 将会返回-1
}



