class Solution
{
public:
    int minEatingSpeed(vector&lt;int&gt; &amp;piles, int h)
    {
        int l = 1, r = *max_element(piles.begin(), piles.end());

        int ans = 0;
        int mid = 0;
        while (l &lt;= r)
        {
            mid = l + (r - l) / 2;
            /*
            这个mid是什么？是速度
            我们要求什么？求时间
            因此我们应该遍历整个香蕉数组， 把用时求出来 和 h 进行比较
            */
            long long h1 = 0; // h1 就是 用时 实际比赛的时候我们其实可以#define int long long
            for (auto &amp;&amp;pile : piles)
            {
                /*
                是熟悉的区间分割诶！
                我的拙劣的讲解视频 BV15QcAefE5j
                区间是 mid
                要划分的变量是 pile
                用时就是 (pile - 1) / mid + 1
                我们其实也可以写成
                (pile + mid - 1) / mid

                by the way 他的本质其实是 pile / mid 结果向上取整
                */

                h1 += (pile - 1) / mid + 1;
            }

            if (h1 &lt;= h) // 当前用时达标！更新答案 放慢速度
            {
                ans = mid;
                r = mid - 1;
            }
            else // 未达标！增加速度
            {
                l = mid + 1;
            }
        }
        return ans;
    }
};
这里有一个很实用的技巧 就是把 速度 → 时间 的变化作为函数封装起来
