f函数参考如下：
int f(vector&lt;int&gt; nums, int m)
    {
        int ans = 1, sum = 0; // 一开始只需要分一段

        for (auto &amp;&amp;i : nums)
        {
            if (sum + i &lt;= m) // 如果最大值没超过 那么最大值可以继续增加
            {
                sum += i;
            }
            else // 超过了就需要增加一段了 与此同时 sum 更新为新的一段
            {
                ans++;
                sum = i;
            }
        }
        return ans;
    }
