bool f(vector&lt;int&gt; v /* 所有楼房高度 */, int e /* 能量 */, int max_ /* 最大建筑高度 */)
{
    for (auto &amp;&amp;i: v)
    {
        if (e &gt; i) e += (e - i);
        else e -= (i - e);

        // 判断是否达到上边界
        if (e &gt;= max) return 1;
        // 判断是否变成负数
        if (e &lt; 0) return 0;
    }
    return 1;
}
