class Solution
{
public:
    int f(vector&lt;int&gt; nums, int lim)
    {
        int ans = 0;
        int r = 0;
        for (int l = 0; l &lt; nums.size(); l++)
        {
            while (r &lt; nums.size() and nums[r] - nums[l] &lt;= lim)
            {
                r++;
            }
            ans += r - l - 1;
        }
        return ans;
