// BIT 树状数组

class BIT
{
private:
    vector&lt;int&gt; c;
    int n;

    int lowbit(int x)
    {
        return x &amp; -x;
    }

public:
    BIT(int size) : n(size)
    {
        c.resize(n + 1, 0);
    }

    BIT(vector&lt;int&gt; &amp;arr) : n(arr.size())
    {
        c.resize(n + 1, 0);
        for (int i = 1; i &lt;= n; i++)
        {
            add(i, arr[i - 1]);
        }
    }

    void add(int i, int val)
    {
        while (i &lt;= n)
        {
            c[i] += val;
            i += lowbit(i);
        }
    }

    int sum(int i)
    {
        int ans = 0;
        while (i)
        {
            ans += c[i];
            i -= lowbit(i);
        }
        return ans;
    }

    int query(int l, int r)
    {
        return sum(r) - sum(l - 1);
    }

    int get(int i)
    {
        return query(i, i);
    }

    int update(int i, int val)
    {
        auto delta = val = get(i);
        add(i, delta);
    }

    void clear()
    {
        fill(all(c), 0);
    }

    // 获取树状数组的大小
    int size()
    {
        return n;
    }
};

