// 快速幂函数，计算 base^exponent mod mod
long long modPow(long long base, long long exponent, long long mod)
{
    long long result = 1;
    base %= mod;
    while (exponent &gt; 0)
    {
        if (exponent &amp; 1)
            result = (result * base) % mod;
        base = (base * base) % mod;
        exponent &gt;&gt;= 1;
    }
    return result;
}

void solve()
{
    long long x, p;
    string y;
    cin &gt;&gt; x &gt;&gt; y &gt;&gt; p;
    // 对 x 取模（防止数字过大）
    x %= p;
    // 特判：若 y 为 &quot;0&quot;，根据数学通常规定 x^0 = 1（注意：0^0一般认为1也可以根据题意而定）
    if (y == &quot;0&quot;)
    {
        cout &lt;&lt; 1 % p &lt;&lt; &quot;\n&quot;;
        return;
    }
    // 答案初始为 1
    long long ans = 1;
    // 对指数 y 的每一位进行处理
    for (char c : y)
    {
        int d = c - &#039;0&#039;;
        // 将当前答案提升 10 次方后再乘上 x^d mod p
        ans = modPow(ans, 10, p);
        ans = (ans * modPow(x, d, p)) % p;
    }
    cout &lt;&lt; ans % p &lt;&lt; &quot;\n&quot;;
}

