    vector&lt;int&gt; indegree(n, 0);          // 统计入度
    vector&lt;int&gt; result;                  // 结果集合
    int s, t;
    while (m--)
    {
        cin &gt;&gt; s &gt;&gt; t;
        indegree[t]++;
        adj[s].push_back(t);
    }

    queue&lt;int&gt; que;
    for (int i = 0; i &lt; n; i++)
    {
        // 入度为0 可以作为开头 加入队列
        if (!indegree[i])
        {
            que.push(i);
        }
    }

    while (que.size())
    {
        auto cur = que.front();
        que.pop();
        result.push_back(cur);

