        {
            for (auto &amp;&amp;i : adj[cur])
            {
                indegree[i]--;
                if (indegree[i] == 0)
                {
                    que.push(i);
                }
            }
        }
    }
    if (result.size() - n)
    {
        cout &lt;&lt; -1;
