// 生成树 prim
void solve()
{
    int v, e;
    cin &gt;&gt; v &gt;&gt; e;
    int vsz = v + 1;

    vector&lt;vector&lt;pair&lt;int, int&gt;&gt;&gt; adj(vsz + 1);
    int v1, v2, val;
    while (e--)
    {
        cin &gt;&gt; v1 &gt;&gt; v2 &gt;&gt; val;
        adj[v1].emplace_back(v2, val);
        adj[v2].emplace_back(v1, val);
    }

    // prim begin
    vector&lt;int&gt; visited(vsz, 0), minDist(vsz, INFLL);
    priority_queue&lt;pair&lt;int, int&gt;, vector&lt;pair&lt;int, int&gt;&gt;, greater&lt;&gt;&gt; pq;

    minDist[1] = 0;
    pq.push({0, 1});

    int totalweight = 0, nodeInMST = 0;

    while (pq.size())
    {
        auto [w, cur] = pq.top();
        pq.pop();

        if (visited[cur])
        {
            continue;
        }

        visited[cur] = 1;
        totalweight += w;
        nodeInMST++;

        for (auto &amp;&amp;[next, nextw] : adj[cur])
        {
            if (visited[next])
            {
                continue;
            }

            if (nextw &lt; minDist[next])
            {
                minDist[next] = nextw;
                pq.push({minDist[next], next});
            }
        }
    }
    if (nodeInMST != v)
    {
        cout &lt;&lt; -1;
        return;
    }
    cout &lt;&lt; totalweight;
}
