树状数组 (Binary Indexed Tree / Fenwick Tree)
树状数组是一种用于高效处理前缀和查询和单点修改的数据结构，时间复杂度为 O(log n)。
核心思想
树状数组利用二进制的性质，通过 lowbit 函数来管理区间。每个位置 i 管理的区间长度为 lowbit(i)。
lowbit 函数
int lowbit(int x) {
    return x &amp; (-x);  // 获取 x 的二进制表示中最低位的 1
}
基本操作
初始化
class BIT {
private:
    vector&lt;int&gt; tree;
    int n;

public:
    BIT(int size) : n(size), tree(size + 1, 0) {}

    // 从数组构造树状数组
    BIT(vector&lt;int&gt;&amp; arr) : n(arr.size()), tree(arr.size() + 1, 0) {
        for (int i = 0; i &lt; arr.size(); i++) {
            update(i + 1, arr[i]);
        }
    }
};
单点修改 (update)
将位置 i 的值增加 delta
void update(int i, int delta) {
    for (; i &lt;= n; i += lowbit(i)) {
        tree[i] += delta;
    }
}
前缀和查询 (query)
查询 [1, i] 的前缀和
int query(int i) {
    int sum = 0;
    for (; i &gt; 0; i -= lowbit(i)) {
        sum += tree[i];
    }
    return sum;
}
区间查询
查询 [l, r] 的区间和
int rangeQuery(int l, int r) {
    return query(r) - query(l - 1);
}
完整代码模板
class BIT {
private:
    vector&lt;int&gt; tree;
    int n;

    int lowbit(int x) {
        return x &amp; (-x);
    }

public:
    BIT(int size) : n(size), tree(size + 1, 0) {}

    // 单点修改：将位置 i 的值增加 delta
    void update(int i, int delta) {
        for (; i &lt;= n; i += lowbit(i)) {
            tree[i] += delta;
        }
    }

    // 前缀和查询：查询 [1, i] 的和
    int query(int i) {
        int sum = 0;
        for (; i &gt; 0; i -= lowbit(i)) {
            sum += tree[i];
        }
        return sum;
    }

    // 区间查询：查询 [l, r] 的和
    int rangeQuery(int l, int r) {
        return query(r) - query(l - 1);
    }

    // 单点查询：查询位置 i 的值
    int pointQuery(int i) {
        return rangeQuery(i, i);
    }
};
高级应用
差分数组 + 树状数组（区间修改，单点查询）
class RangeUpdateBIT {
private:
    BIT diff;  // 差分数组的树状数组

public:
    RangeUpdateBIT(int n) : diff(n) {}

    // 区间修改：将 [l, r] 的值都增加 delta
    void rangeUpdate(int l, int r, int delta) {
        diff.update(l, delta);
        diff.update(r + 1, -delta);
    }

    // 单点查询：查询位置 i 的值
    int pointQuery(int i) {
        return diff.query(i);
    }
};
二维树状数组
class BIT2D {
private:
    vector&lt;vector&lt;int&gt;&gt; tree;
    int n, m;

    int lowbit(int x) { return x &amp; (-x); }

public:
    BIT2D(int rows, int cols) : n(rows), m(cols), tree(rows + 1, vector&lt;int&gt;(cols + 1, 0)) {}

    void update(int x, int y, int delta) {
        for (int i = x; i &lt;= n; i += lowbit(i)) {
            for (int j = y; j &lt;= m; j += lowbit(j)) {
                tree[i][j] += delta;
            }
        }
    }

    int query(int x, int y) {
        int sum = 0;
        for (int i = x; i &gt; 0; i -= lowbit(i)) {
            for (int j = y; j &gt; 0; j -= lowbit(j)) {
                sum += tree[i][j];
            }
        }
        return sum;
    }

    int rangeQuery(int x1, int y1, int x2, int y2) {
        return query(x2, y2) - query(x1 - 1, y2) - query(x2, y1 - 1) + query(x1 - 1, y1 - 1);
    }
};
使用场景

动态前缀和：频繁的单点修改和前缀和查询
逆序对统计：利用树状数组统计逆序对个数
离散化 + 树状数组：处理大范围但稀疏的数据
差分数组优化：区间修改转化为单点修改

时间复杂度

单点修改：O(log n)
前缀和查询：O(log n)
区间查询：O(log n)
空间复杂度：O(n)

注意事项

树状数组的下标从 1 开始，不是从 0 开始
lowbit(x) 的原理：x &amp; (-x) 可以提取 x 的最低位 1
树状数组只能处理可逆的操作（如加法、异或），不能处理最值操作

ACM-research/数据结构与算法/数据结构/线段树.content:
线段树 (Segment Tree)
线段树是一种用于处理区间查询和区间修改的高效数据结构，支持在 O(log n) 时间内完成各种区间操作。
核心思想
线段树是一棵完全二叉树，每个节点代表一个区间，叶子节点代表单个元素，内部节点代表子区间的合并结果。
基本性质

父节点区间 = 左子树区间 ∪ 右子树区间
对于节点 i：左儿子为 2*i，右儿子为 2*i+1
树的高度为 O(log n)，节点总数约为 4n

基础线段树（区间查询，单点修改）
class SegmentTree {
private:
    vector&lt;int&gt; tree;
    int n;

    void build(vector&lt;int&gt;&amp; arr, int node, int start, int end) {
        if (start == end) {
            tree[node] = arr[start];
        } else {
            int mid = (start + end) / 2;
            build(arr, 2*node, start, mid);
            build(arr, 2*node+1, mid+1, end);
            tree[node] = tree[2*node] + tree[2*node+1];  // 区间和
        }
    }

    void updateHelper(int node, int start, int end, int idx, int val) {
        if (start == end) {
            tree[node] = val;
        } else {
            int mid = (start + end) / 2;
            if (idx &lt;= mid) {
                updateHelper(2*node, start, mid, idx, val);
            } else {
                updateHelper(2*node+1, mid+1, end, idx, val);
            }
            tree[node] = tree[2*node] + tree[2*node+1];
        }
    }

    int queryHelper(int node, int start, int end, int l, int r) {
        if (r &lt; start || end &lt; l) {
            return 0;  // 区间不相交
        }
        if (l &lt;= start &amp;&amp; end &lt;= r) {
            return tree[node];  // 区间完全包含
        }
        int mid = (start + end) / 2;
        int p1 = queryHelper(2*node, start, mid, l, r);
        int p2 = queryHelper(2*node+1, mid+1, end, l, r);
        return p1 + p2;
    }

public:
    SegmentTree(vector&lt;int&gt;&amp; arr) {
        n = arr.size();
        tree.resize(4 * n);
        build(arr, 1, 0, n-1);
    }

    void update(int idx, int val) {
        updateHelper(1, 0, n-1, idx, val);
    }

    int query(int l, int r) {
        return queryHelper(1, 0, n-1, l, r);
    }
};
懒惰传播（Lazy Propagation）
对于区间修改操作，使用懒惰传播避免不必要的递归：
class LazySegmentTree {
private:
    vector&lt;long long&gt; tree, lazy;
    int n;

    void push(int node, int start, int end) {
        if (lazy[node] != 0) {
            tree[node] += lazy[node] * (end - start + 1);
            if (start != end) {  // 不是叶子节点
                lazy[2*node] += lazy[node];
                lazy[2*node+1] += lazy[node];
            }
            lazy[node] = 0;
        }
    }

    void build(vector&lt;int&gt;&amp; arr, int node, int start, int end) {
        if (start == end) {
            tree[node] = arr[start];
        } else {
            int mid = (start + end) / 2;
            build(arr, 2*node, start, mid);
            build(arr, 2*node+1, mid+1, end);
            tree[node] = tree[2*node] + tree[2*node+1];
        }
    }

    void updateRange(int node, int start, int end, int l, int r, int val) {
        push(node, start, end);
        if (start &gt; r || end &lt; l) return;

        if (start &gt;= l &amp;&amp; end &lt;= r) {
            lazy[node] += val;
            push(node, start, end);
            return;
        }

        int mid = (start + end) / 2;
        updateRange(2*node, start, mid, l, r, val);
        updateRange(2*node+1, mid+1, end, l, r, val);

        push(2*node, start, mid);
        push(2*node+1, mid+1, end);
        tree[node] = tree[2*node] + tree[2*node+1];
    }

    long long queryRange(int node, int start, int end, int l, int r) {
        if (start &gt; r || end &lt; l) return 0;

        push(node, start, end);
        if (start &gt;= l &amp;&amp; end &lt;= r) {
            return tree[node];
        }

        int mid = (start + end) / 2;
        long long p1 = queryRange(2*node, start, mid, l, r);
        long long p2 = queryRange(2*node+1, mid+1, end, l, r);
        return p1 + p2;
    }

public:
    LazySegmentTree(vector&lt;int&gt;&amp; arr) {
        n = arr.size();
        tree.resize(4 * n);
        lazy.resize(4 * n, 0);
        build(arr, 1, 0, n-1);
    }

    void updateRange(int l, int r, int val) {
        updateRange(1, 0, n-1, l, r, val);
    }

    long long query(int l, int r) {
        return queryRange(1, 0, n-1, l, r);
    }

    void updatePoint(int idx, int val) {
        updateRange(idx, idx, val);
    }
};
不同类型的线段树
1. 最值线段树（RMQ）
// 将 tree[node] = tree[2*node] + tree[2*node+1] 改为：
tree[node] = max(tree[2*node], tree[2*node+1]);  // 最大值
tree[node] = min(tree[2*node], tree[2*node+1]);  // 最小值
2. 乘法懒惰传播
struct LazyNode {
    long long add, mul;
    LazyNode() : add(0), mul(1) {}
};

void push(int node, int start, int end) {
    if (lazy[node].mul != 1 || lazy[node].add != 0) {
        tree[node] = tree[node] * lazy[node].mul + lazy[node].add * (end - start + 1);
        if (start != end) {
            // 传播到子节点
            lazy[2*node].mul *= lazy[node].mul;
            lazy[2*node].add = lazy[2*node].add * lazy[node].mul + lazy[node].add;
            lazy[2*node+1].mul *= lazy[node].mul;
            lazy[2*node+1].add = lazy[2*node+1].add * lazy[node].mul + lazy[node].add;
        }
        lazy[node] = LazyNode();  // 重置
    }
}
3. 动态开点线段树
struct Node {
    int left, right;
    long long val, lazy;
    Node() : left(-1), right(-1), val(0), lazy(0) {}
};

class DynamicSegmentTree {
private:
    vector&lt;Node&gt; nodes;
    int nodeCount;
    int L, R;  // 值域范围

    int newNode() {
        nodes.emplace_back();
        return nodeCount++;
    }

public:
    DynamicSegmentTree(int l, int r) : L(l), R(r), nodeCount(0) {
        nodes.reserve(4000000);  // 预分配空间
        newNode();  // 创建根节点
    }

    void update(int l, int r, int val) { updateRange(0, L, R, l, r, val); }
    long long query(int l, int r) { return queryRange(0, L, R, l, r); }

    // ... 其他函数实现类似，但需要动态创建节点
};
