void solve()
{
    int n, m;
    cin &gt;&gt; n &gt;&gt; m;
    vector&lt;int&gt; v(n + 1);
    // 要建立有向边
    vector adj(n + 1, vector&lt;pair&lt;int, int&gt;&gt;());
    for (int i = 1; i &lt;= m; i++)
    {
        int u, v, w;
        cin &gt;&gt; u &gt;&gt; v &gt;&gt; w;
        adj[u].emplace_back(w, v);
    }

    // 1 和 n 分别做源点 跑dij

    vector minDist(n + 1, vector&lt;int&gt;(n + 1, LLONG_MAX));
    for (int i = 1; i &lt;= n; i++)
    {
        minDist[i][i] = 0;
    }

    auto dij = [&amp;](int u, int fa) -&gt; void
    {
        priority_queue&lt;pair&lt;int, int&gt;, vector&lt;pair&lt;int, int&gt;&gt;, greater&lt;pair&lt;int, int&gt;&gt;&gt; pq;
        // 按照 {边，中继点} 存储 遍历到这个点的时候 查找它的儿子 
        // 进行松弛操作

        for (auto [w, v] : adj[u])
        {
            pq.push({w, v});
            minDist[u][v] = w; // 初始化
        }

        while (pq.size())
        {
            auto [curw, curv] = pq.top();
            pq.pop();

            // 我需要跑堆优化的dij
            for (auto [w, v] : adj[curv])
            {
                if (curw + w &lt; minDist[u][v])
                {
                    minDist[u][v] = curw + w;
                    pq.push({minDist[u][v], v});
                }
            }
        }
    };

    dij(1, 0);
    dij(n, 0);

    for (int i = 1; i &lt;= n; i++)
    {
        cout &lt;&lt; minDist[1][i] &lt;&lt; &#039; &#039; &lt;&lt; minDist[n][i] &lt;&lt; endl;
    }
}

