void solve()
{
    int n;
    cin &gt;&gt; n;
    vector adj(n + 1, vector&lt;int&gt;());
    for (int i = 1; i &lt;= n; i++)
    {
        int op;
        cin &gt;&gt; op;
        while (op--)
        {
            int x;
            cin &gt;&gt; x;
            adj[i].emplace_back(x);
        }
    }

    vector vis(n + 1, vector&lt;int&gt;(3));
    set&lt;pair&lt;int, int&gt;&gt; st;
    vector&lt;int&gt; ans(n + 1);

    function&lt;int(int, int)&gt; dfs = [&amp;](int u, int idx) -&gt; int // u从idx走进来 问有多少条不同路径
    {
        if (idx != -1)
        {
            // 判断是否进入环
            if (vis[u][idx])
            {
                return st.size();
            }
            vis[u][idx] = 1;
        }

        idx = (idx + 1) % adj[u].size();
        auto nxt = adj[u][idx];
        int res = 0;
        st.insert({min(nxt, u), max(nxt, u)});

        for (int i = 0; i &lt; adj[nxt].size(); i++)
        {
            if (adj[nxt][i] == u)
            {
                res = dfs(nxt, i);
                break;
            }
        }

        if (idx == 0)
        {
            ans[u] = res;
        }
        return res;
    };

    for (int i = 1; i &lt;= n; i++)
    {
        st.clear();
        if (!ans[i])
        {
            dfs(i, -1);
        }
        cout &lt;&lt; ans[i] &lt;&lt; endl;
    }
}
