constexpr int MOD = 998244353;
// -9.2e18 ~ 9.2e18

int add(int i, int j)
{
    return (i + j) % MOD;
}

int mul(int i, int j)
{
    return (i % MOD * j % MOD) % MOD;
}

int ksm(int base, int exp)
{
    int ans = 1;
    while (exp)
    {
        if (exp &amp; 1)
        {
            ans = mul(ans, base);
        }
        base = mul(base, base);
        exp &gt;&gt;= 1;
    }
    return ans;
}

void solve()
{
    int n;
    cin &gt;&gt; n;
    vector&lt;int&gt; v(n + 1);
    for (int i = 1; i &lt;= n; i++)
    {
        cin &gt;&gt; v[i];
    }

    vector&lt;int&gt; vis(n + 1);
    vector&lt;int&gt; odd, even2, even4;
    for (int i = 1; i &lt;= n; i++)
    {
        if (vis[i])
        {
            continue;
        }

        auto cur = i;
        int tot = 0;
        while (!vis[cur])
        {
            tot++;
            vis[cur] = 1;
            cur = v[cur];
        }
        if (tot &amp; 1)
        {
            odd.emplace_back(tot);
        }
        else
        {
            if (tot == 2)
            {
                even2.emplace_back(tot);
            }
            else
            {
                even4.emplace_back(tot);
            }
        }
    }

    if (odd.size() &gt; 2)
    {
        return void(cout &lt;&lt; 0);
    }

    if (odd.size() == 2)
    {
        cout &lt;&lt; mul(mul(odd[0], odd[1]), ksm(2, even4.size()));
        return;
    }

    // 现在全都是偶数 要求和
    int ans = 0;
    // 如果把2删掉 那就删没了 所以对于每一个2 把他删掉的结果都是  ksm(2, even4.size())
    // 所以这样的贡献一共有 even2.size() 个 要乘起来

    ans = add(ans, mul(ksm(2, even4.size()), even2.size()));

    // 如果把4删掉 对于每一个大于等于4的 删掉会导致 他的贡献是 ksm(num / 2, 2);
    // 剩下even4.size() - 1 个 4 贡献是ksm(2, even4.size() - 1)
    // 2的贡献都不用管的

    for (auto num : even4)
    {
        ans = add(ans, mul(ksm(num / 2, 2), ksm(2, even4.size() - 1)));
    }
    cout &lt;&lt; ans;
}
