一个好点需要同时满足 y-x&lt;k_1, y+x&lt;k_2 ，对于这样的问题，一个经典的trick是对一个权重排序，比较另一个权重。
在本题中，不妨记录 y-x=A, y+x=B 。我们可以采用排序并遍历 A 和 k_1 ，在遍历 k_{1} 的过程中，动态往一个数据结构中加入所有满足 A&lt;k_1 的 B ，等到这个步骤执行完，实际上 y-x&lt;k_1 的条件已经得到满足，我们在该结构中查询所有满足 B&lt;k_2 的 B  的数量即可。这样两个条件都能得到满足，所以答案是合理的。
在实现上，我们需要一个高效的单点更新值，区间查询和的数据结构，可以考虑gnu提供的平衡树 或者树状数组/线段树。需要注意的是，由于B, k_2 的值太多，我们需要首先统计所有的 B, k_2 然后离散化处理。
下面分别给出线段树版本和 pbds::ordered_{}multiset 版本

线段树版本

// #pragma GCC optimize(2)
#include &lt;bits/stdc++.h&gt;
using namespace std;
#define int long long
#define endl &#039;\n&#039;
#define all(x) (x).begin(), (x).end()

constexpr int MOD = 1e9 + 7;
// -9.2e18 ~ 9.2e18

const int N = 1e6;
vector&lt;int&gt; sum(N &lt;&lt; 2), ad(N &lt;&lt; 2);
#define mid ((l + r) &gt;&gt; 1)

void lazy(int i, int v, int n)
{
    sum[i] += v * n;
    ad[i] += v;
}

void up(int i)
{
    sum[i] = sum[i &lt;&lt; 1] + sum[i &lt;&lt; 1 | 1];
}

void down(int i, int ln, int rn)
{
    if (ad[i])
    {
        lazy(i &lt;&lt; 1, ad[i], ln);
        lazy(i &lt;&lt; 1 | 1, ad[i], rn);
        ad[i] = 0;
    }
}

void update(int jobl, int jobr, int v, int l, int r, int i)
{
    if (jobl &lt;= l and jobr &gt;= r)
    {
        lazy(i, v, r - l + 1);
        return;
    }
    down(i, mid - l + 1, r - mid);
    if (jobl &lt;= mid)
    {
        update(jobl, jobr, v, l, mid, i &lt;&lt; 1);
    }
    if (jobr &gt; mid)
    {
        update(jobl, jobr, v, mid + 1, r, i &lt;&lt; 1 | 1);
    }
    up(i);
}

int query(int jobl, int jobr, int l, int r, int i)
{
    if (jobl &lt;= l and jobr &gt;= r)
    {
        return sum[i];
    }

    down(i, mid - l + 1, r - mid);
    int ans = 0;
    if (jobl &lt;= mid)
    {
        ans += query(jobl, jobr, l, mid, i &lt;&lt; 1);
    }
    if (jobr &gt; mid)
    {
        ans += query(jobl, jobr, mid + 1, r, i &lt;&lt; 1 | 1);
    }
    return ans;
}

void build(int l, int r, int i)
{
    ad[i] = 0;
    if (l == r)
    {
        sum[i] = 0;
        return;
    }

    build(l, mid, i &lt;&lt; 1);
    build(mid + 1, r, i &lt;&lt; 1 | 1);
    up(i);
}

void solve()
{
    int n, q;
    cin &gt;&gt; n &gt;&gt; q;

    /*
    记y-x=A, y+x=B
    我们要让 A&lt;k1的同时B&lt;k2
    这是一个很典的偏序查找问题
    我们可以对k1和A排序 遍历k1 对所有满足A&lt;k1的{A,B} 加入B到线段树中
    然后logn查找满足k2&gt;B的所有B 记录答案
    */

    vector&lt;pair&lt;int, int&gt;&gt; v(n);
    for (int i = 0; i &lt; n; i++)
    {
        cin &gt;&gt; v[i].first &gt;&gt; v[i].second;
    }

    struct datas
    {
        int k1, k2, idx;
    };

    vector&lt;datas&gt; d(q);
    for (int i = 0; i &lt; q; i++)
    {
        cin &gt;&gt; d[i].k1 &gt;&gt; d[i].k2;
        d[i].idx = i + 1;
    }

    vector&lt;pair&lt;int, int&gt;&gt; vv;
    for (auto [x, y] : v)
    {
        vv.emplace_back(y - x, y + x);
    }

    sort(all(vv));
    sort(all(d), [](auto a, auto b)
         { return a.k1 &lt; b.k1; });

    // 需要先收集所有的B
    vector&lt;int&gt; itob;
    itob.emplace_back(LLONG_MIN);
    for (auto [_, B] : vv)
    {
        itob.emplace_back(B);
    }
    for (int i = 0; i &lt; q; i++)
    {
        itob.emplace_back(d[i].k2);
    }
    sort(all(itob));
    itob.erase(unique(all(itob)), itob.end());

    // itob是1-based
    auto nn = itob.size() + 10;
    build(1, nn, 1);

    int idx = 0;
    vector&lt;int&gt; ans(q + 1);
    for (int i = 0; i &lt; q; i++)
    {
        auto [k1, k2, id] = d[i];

        while (idx &lt; vv.size() and vv[idx].first &lt; k1)
        {
            auto [A, B] = vv[idx];
            auto it = lower_bound(all(itob), B);
            auto dist = it - begin(itob);
            update(dist, dist, 1, 1, nn, 1);
            idx++;
        }

        auto pos = lower_bound(all(itob), k2) - begin(itob);
        if (pos &lt;= 1)
        {
            ans[id] = 0;
        }
        else
        {
            ans[id] = query(1, pos - 1, 1, nn, 1);
        }
    }
    for (int i = 1; i &lt;= q; i++)
    {
        cout &lt;&lt; ans[i] &lt;&lt; endl;
    }
}

signed main()
{
    cin.tie(0)-&gt;ios::sync_with_stdio(0);
    cout &lt;&lt; setiosflags(ios::fixed) &lt;&lt; setprecision(2);
    int TT = 1;
    // cin &gt;&gt; TT;
    while (TT--)
    {
        solve();
        // cout &lt;&lt; endl;
    }
}

