if (n % 3 == 0)
{
	return quickmod(3, n / 3, mod) % mod;
}
if (n % 3 == 1)
{
	n -= 4;
	return 4 * quickmod(3, n / 3, mod) % mod;
}
if (n % 3 == 2)
{
	n -= 2;
	return 2 * quickmod(3, n / 3, mod) % mod;
}

也可以这么写：
auto tail = n % 3 == 0 ? 1 : (n % 3 == 1 ? 4 : 2);
auto power = tail == 1 ? n : (n - tail) / 3;
return quickmod(3, power, mod) * tail % mod;
