		en = curen;
		ans++;
	}
}
return ans;
题目4
给定若干会议的开始，结束时间
任何会议的召开期间 你只需要抽出一天来参加
但是 同一天只能参加一个会议
返回你能参加的最大会议数量

思路：
等价于牛客寒假H
两种做法 一种是维护一个小根堆 一种是集合 + 二分

二分做法
int n, ans = 0, last = -1;
cin &gt;&gt; n;
vector&lt;pair&lt;int, int&gt;&gt; v(n);
for (auto &amp;&amp;[a, b] : v) cin &gt;&gt; a &gt;&gt; b; last = max(last, b);
ranges::sort(v, [](auto &amp;&amp;v1, auto &amp;&amp;v2)
{
	auto [a, b] = v1, [c, d] = v2;
	return a == c ? b &lt; d : a &lt; c;	
});
set&lt;int&gt; st;
for (int i = 1; i &lt;= last; i++) st.insert(i);

for (auto &amp;&amp;[a, b] : v)
{
	auto it = st.lower_bound(a);
	if (it != st.end() and *it &lt;= r)
	{
		ans++;
		st.erase(*it);
	}
}

cout &lt;&lt; ans;
小根堆做法：
int n, ans = 0;
cin &gt;&gt; n;
vector&lt;pair&lt;int, int&gt;&gt; v(n);
map&lt;int, vector&lt;int&gt;&gt; mp;
for (auto &amp;&amp;[a, b] : v) 
{
	cin &gt;&gt; a &gt;&gt; b;
	mp[a].emplace_back(b);
}

priority_queue&lt;int, vector&lt;int&gt;, greater&lt;int&gt;&gt; pq;
int index = 1;
for (auto &amp;&amp;i : mp[index]) pq.push(i);
while (pq.size())
{
	while (pq.size() and pq.top() &lt; index) pq.pop();
	if (!pq.empty()) 
	{
		pq.pop();
		ans++;
		index++;
		for (auto &amp;&amp;i : mp[index]) pq.push(i);
	}
}
